export function pageParamPathSegments(pageParamKey) {
    return pageParamKey.split(".");
}
export function getValueAtPath(value, pageParamKey) {
    const path = pageParamPathSegments(pageParamKey);
    let current = value;
    for (const segment of path) {
        if (typeof current !== "object" ||
            current === null ||
            !(segment in current)) {
            return undefined;
        }
        current = current[segment];
    }
    return current;
}
export function setValueAtPath(value, pageParamKey, pageParam) {
    const path = pageParamPathSegments(pageParamKey);
    const result = { ...value };
    let source = value;
    let target = result;
    for (let i = 0; i < path.length - 1; i++) {
        const key = path[i];
        const sourceNext = source[key];
        const targetNext = typeof sourceNext === "object" && sourceNext !== null
            ? { ...sourceNext }
            : {};
        target[key] = targetNext;
        target = targetNext;
        source =
            typeof sourceNext === "object" && sourceNext !== null
                ? sourceNext
                : {};
    }
    target[path[path.length - 1]] = pageParam;
    return result;
}
